/** Clean, whole-sentence answers (EN + HU), merged into KNOWLEDGE. Keywords match at a
 *  WORD START; ambiguous short words only appear inside phrases. */
export const DESIGN_KNOWLEDGE: KnowledgeEntry[] = [
  // ── layout ───────────────────────────────────────────────────────────────────
  { topic: 'flexbox', keywords: ['flexbox', 'flex box', 'display flex', 'display: flex', 'justify-content', 'align-items'], en: 'Flexbox lays items out in ONE direction, a row or a column. The container gets display: flex; justify-content spaces items along the main axis, align-items aligns them across it, gap adds space between them, flex-wrap lets them wrap, and flex: 1 lets an item grow to fill the free space.', hu: 'A Flexbox EGY irányban rendez: sorba vagy oszlopba. A konténer display: flex-et kap; a justify-content a fő tengely mentén osztja el az elemeket, az align-items keresztben igazít, a gap térközt ad közéjük, a flex-wrap tördel, a flex: 1 pedig kitölti a szabad helyet.' },
  { topic: 'css-grid', keywords: ['css grid', 'grid layout', 'display grid', 'display: grid', 'grid-template', 'grid template areas', 'rácsos elrendezés', 'grid elrendezés'], en: 'CSS Grid lays items out in TWO dimensions, rows and columns at once. Define tracks with grid-template-columns (fr units share the free space, repeat(auto-fit, minmax(200px, 1fr)) makes a self-wrapping card grid), place items by line numbers or named grid-template-areas, and space them with gap.', hu: 'A CSS Grid KÉT dimenzióban rendez: egyszerre sorokban és oszlopokban. A sávokat a grid-template-columns adja meg (az fr egység osztja el a szabad helyet, a repeat(auto-fit, minmax(200px, 1fr)) magától tördelő kártyarácsot ad), az elemeket vonalszámmal vagy elnevezett grid-template-areas területekkel helyezed el, a térközt a gap adja.' },
  { topic: 'flex-or-grid', keywords: ['flexbox or grid', 'grid or flexbox', 'flexbox vagy grid', 'grid vagy flexbox', 'when to use grid', 'mikor használjak gridet'], en: 'Use flexbox for one-dimensional things — a navbar, a row of buttons, centring one element, items whose size comes from their content. Use grid for two-dimensional page and card layouts where rows and columns must line up. They combine well: a grid page whose cells use flexbox inside.', hu: 'Flexboxot egydimenziós dolgokra használj — navigációs sáv, gombsor, egy elem középre tétele, tartalom szerint méreteződő elemek. Gridet kétdimenziós oldal- és kártyaelrendezésekre, ahol a soroknak és az oszlopoknak egy vonalba kell esniük. Jól kombinálhatók: grid az oldalnak, flexbox a cellák belsejében.' },
  { topic: 'box-model', keywords: ['box model', 'dobozmodell', 'box-sizing', 'border-box'], en: 'Every element is a box: content, then padding, then border, then margin. By default width only covers the content, so padding and border make the box bigger; box-sizing: border-box makes width include padding and border, which is why most resets set it on every element.', hu: 'Minden elem egy doboz: tartalom, körülötte padding, aztán border, végül margin. Alapból a width csak a tartalomra vonatkozik, így a padding és a border megnöveli a dobozt; a box-sizing: border-box mellett a width a paddinget és a bordert is tartalmazza, ezért a legtöbb reset minden elemre beállítja.' },
  { topic: 'css-position', keywords: ['position absolute', 'position relative', 'position sticky', 'position fixed', 'css position', 'pozicionálás', 'z-index'], en: 'position decides how an element is placed: static is the normal flow, relative shifts it from its normal place, absolute places it relative to the nearest positioned ancestor, fixed pins it to the viewport, and sticky keeps it in flow until it hits an edge while scrolling. z-index orders overlapping positioned elements within the same stacking context.', hu: 'A position dönti el, hogyan kerül helyre egy elem: a static a normál folyam, a relative a saját helyéhez képest tolja el, az absolute a legközelebbi pozicionált őshöz képest helyezi el, a fixed a képernyőhöz rögzíti, a sticky pedig görgetéskor egy szélhez tapad. A z-index az egymást fedő pozicionált elemek sorrendjét adja meg ugyanazon a rétegzési kontextuson belül.' },
  { topic: 'responsive-design', keywords: ['responsive design', 'reszponzív', 'responsive', 'mobile first', 'mobile-first', 'breakpoint', 'töréspont'], en: 'Responsive design makes one page work on every screen. Start mobile-first with a single column, use flexible units (%, fr, rem, clamp()), images with max-width: 100%, and add media queries — or container queries for components — at the widths where the layout breaks, not at specific device sizes. Always include the viewport meta tag.', hu: 'A reszponzív dizájn révén egy oldal minden képernyőn működik. Kezdj mobile-first, egy oszloppal, használj rugalmas egységeket (%, fr, rem, clamp()), a képekre max-width: 100%-ot, és ott tegyél media queryt — komponensekre container queryt —, ahol az elrendezés szétesik, nem konkrét eszközméreteknél. A viewport meta tag mindig legyen ott.' },
  { topic: 'css-units', keywords: ['css units', 'css mértékegység', 'css mertekegyseg', 'rem vagy em', 'rem or em', 'viewport units', 'dvh'], en: 'px is fixed; rem is relative to the root font size (great for type and spacing, respects user settings); em is relative to the element’s own font size; % is relative to the parent; vw/vh are 1% of the viewport, and dvh/svh fix the mobile address-bar jump; ch is the width of a "0" — handy for line length (max-width: 65ch).', hu: 'A px fix; a rem a gyökér betűméretéhez viszonyít (tipográfiára és térközökre ideális, tiszteli a felhasználói beállítást); az em az elem saját betűméretéhez; a % a szülőhöz; a vw/vh a képernyő 1%-a, a dvh/svh pedig kiküszöböli a mobilos címsor-ugrást; a ch egy „0” szélessége — sorhosszra jó (max-width: 65ch).' },
  { topic: 'centering', keywords: ['center a div', 'center in css', 'középre igazítás', 'kozepre igazitas', 'vertical center', 'függőleges középre', 'place-items'], en: 'The shortest way to centre anything: display: grid; place-items: center; on the parent. With flexbox: display: flex; justify-content: center; align-items: center. For a block with a known width: margin-inline: auto. For text: text-align: center.', hu: 'A legrövidebb középre tétel: a szülőre display: grid; place-items: center;. Flexboxszal: display: flex; justify-content: center; align-items: center. Ismert szélességű blokkra: margin-inline: auto. Szövegre: text-align: center.' },
  { topic: 'layout-patterns', keywords: ['holy grail layout', 'sidebar layout', 'oldalsáv elrendezés', 'layout pattern', 'elrendezési minta', 'sticky footer', 'full bleed'], en: 'Common layout patterns: the holy-grail layout (header, sidebar, main, footer) with grid-template-areas; a sidebar that collapses under the content on small screens; a sticky footer with min-height: 100dvh and a flex/grid column; a centred content column with max-width and margin-inline: auto; and full-bleed sections that break out of it to span the whole width.', hu: 'Gyakori elrendezési minták: a holy-grail elrendezés (fejléc, oldalsáv, tartalom, lábléc) grid-template-areas-szel; kis képernyőn a tartalom alá csúszó oldalsáv; ragadós lábléc min-height: 100dvh-val és flex/grid oszloppal; középre tett tartalomoszlop max-width-del és margin-inline: auto-val; és a teljes szélességre kifutó (full-bleed) szakaszok.' },

  // ── the cascade & selectors ──────────────────────────────────────────────────
  { topic: 'css-selectors', keywords: ['css selector', 'css szelektor', 'szelektor', 'selectors', 'pseudo-class', 'pszeudo-osztály', 'attribute selector'], en: 'Selectors pick elements: tag (p), class (.card), id (#logo), attribute ([type="email"]), descendant (nav a), child (ul > li), sibling (h2 + p), and pseudo-classes for states and positions — :hover, :focus-visible, :checked, :disabled, :first-child, :nth-child(2n), :not(), :is(), :where() and :has().', hu: 'A szelektorok választják ki az elemeket: tag (p), osztály (.card), id (#logo), attribútum ([type="email"]), leszármazott (nav a), közvetlen gyerek (ul > li), testvér (h2 + p), valamint állapot- és helyzet-pszeudoosztályok — :hover, :focus-visible, :checked, :disabled, :first-child, :nth-child(2n), :not(), :is(), :where() és :has().' },
  { topic: 'specificity', keywords: ['specificity', 'specificitás', 'specificitas', 'the cascade', 'a kaszkád', '!important', 'which css rule wins', 'melyik css szabály'], en: 'When rules conflict the cascade decides: first origin and !important, then cascade layers, then specificity — ids (1,0,0) beat classes, attributes and pseudo-classes (0,1,0), which beat tags (0,0,1) — and finally source order, the later rule wins. :where() has zero specificity; avoid !important and ids for styling to keep CSS easy to override.', hu: 'Ütközéskor a kaszkád dönt: először az eredet és az !important, aztán a cascade layerek, majd a specificitás — az id (1,0,0) erősebb az osztálynál, attribútumnál és pszeudoosztálynál (0,1,0), azok pedig a tagnél (0,0,1) —, végül a forrássorrend: a későbbi szabály nyer. A :where() specificitása nulla; kerüld az !importantot és az id-alapú stílusozást, hogy a CSS könnyen felülírható maradjon.' },
  { topic: 'pseudo-elements', keywords: ['pseudo-element', 'pseudo element', 'pszeudoelem', 'pszeudo-elem', '::before', '::after', 'before and after'], en: '::before and ::after insert a decorative box before or after an element’s content (they need content: ""), ideal for icons, underlines, overlays and badges without extra HTML. Others: ::placeholder, ::selection, ::marker for list bullets, ::first-letter and ::backdrop behind dialogs.', hu: 'A ::before és ::after díszítő dobozt szúr be az elem tartalma elé vagy mögé (kell nekik content: ""), ideális ikonokhoz, aláhúzásokhoz, rátétekhez és jelvényekhez extra HTML nélkül. Továbbiak: ::placeholder, ::selection, ::marker a listajelekhez, ::first-letter és ::backdrop a dialógusok mögött.' },
  { topic: 'css-variables', keywords: ['css variables', 'css variable', 'css változó', 'css valtozo', 'custom properties', 'custom property'], en: 'Custom properties store reusable values: define --primary: #3b82f6 on :root and use it with var(--primary, fallback). They cascade and inherit, can change inside media queries, themes ([data-theme="dark"]) or components, and JavaScript can read and set them — the basis of theming and design tokens in plain CSS.', hu: 'Az egyéni tulajdonságok (CSS-változók) újrahasználható értékeket tárolnak: a :root-on add meg (--primary: #3b82f6), és var(--primary, tartalék)-kal használd. Kaszkádolnak és öröklődnek, változhatnak media queryben, témában ([data-theme="dark"]) vagy komponensben, és JavaScript is olvashatja, írhatja őket — ez a témázás és a design tokenek alapja sima CSS-ben.' },
  { topic: 'cascade-layers', keywords: ['cascade layers', 'cascade layer', '@layer', 'css layer'], en: '@layer groups CSS into ordered layers — for example @layer reset, base, components, utilities; — and a later layer beats an earlier one regardless of specificity. It makes third-party CSS and your own styles predictable without specificity wars or !important.', hu: 'Az @layer rendezett rétegekbe csoportosítja a CSS-t — például @layer reset, base, components, utilities; —, és a későbbi réteg a specificitástól függetlenül nyer a korábbival szemben. Így a külső CSS és a saját stílusok specificitás-háború és !important nélkül is kiszámíthatók.' },
  { topic: 'css-nesting', keywords: ['css nesting', 'nested css', 'css beágyazás', 'beágyazott css'], en: 'Native CSS nesting lets you write rules inside rules like in Sass: .card { padding: 1rem; &:hover { … } & .title { … } @media (width > 600px) { … } }. & refers to the parent selector. It is supported in all modern browsers since 2023.', hu: 'A natív CSS-beágyazással szabályt írhatsz szabályon belül, mint a Sassban: .card { padding: 1rem; &:hover { … } & .title { … } @media (width > 600px) { … } }. Az & a szülő szelektort jelenti. 2023 óta minden modern böngésző támogatja.' },

  // ── modern CSS ───────────────────────────────────────────────────────────────
  { topic: 'container-queries', keywords: ['container query', 'container queries', 'konténer lekérdezés', 'container-type', '@container'], en: 'Container queries style a component by the size of ITS container instead of the viewport: give the wrapper container-type: inline-size, then write @container (width > 400px) { … }. The same card can be a vertical stack in a narrow sidebar and a horizontal row in the wide main column. Units cqi/cqw are relative to the container.', hu: 'A container query egy komponenst a SAJÁT konténere mérete szerint stílusoz, nem a képernyő szerint: a burkoló kap container-type: inline-size-t, utána @container (width > 400px) { … }. Ugyanaz a kártya függőleges lehet a keskeny oldalsávban és vízszintes a széles tartalomban. A cqi/cqw egységek a konténerhez viszonyítanak.' },
  { topic: 'has-selector', keywords: [':has()', 'has() szelektor', 'has() selector', ':has(', 'has selector', 'has() selector', 'parent selector', 'szülő szelektor', 'szulo szelektor'], en: ':has() is the "parent selector": it matches an element by what it contains or what follows it — .card:has(img) styles cards with an image, form:has(:invalid) marks a form with errors, label:has(+ input:focus) styles a label whose input is focused. Supported in all modern browsers since late 2023.', hu: 'A :has() a „szülő szelektor”: egy elemet aszerint választ ki, mit tartalmaz vagy mi követi — a .card:has(img) a képes kártyákat stílusozza, a form:has(:invalid) a hibás űrlapot jelöli, a label:has(+ input:focus) a fókuszban lévő mező címkéjét. 2023 vége óta minden modern böngésző támogatja.' },
  { topic: 'clamp', keywords: ['clamp()', 'css clamp', 'fluid typography', 'folyékony tipográfia', 'fluid type', 'fluid spacing'], en: 'clamp(min, preferred, max) picks the preferred value but never goes below min or above max — font-size: clamp(1rem, 0.9rem + 1vw, 1.5rem) grows smoothly with the screen without media queries. min() and max() pick the smaller or larger value, e.g. width: min(100% - 2rem, 70ch).', hu: 'A clamp(min, preferált, max) a preferált értéket adja, de sosem megy a min alá és a max fölé — a font-size: clamp(1rem, 0.9rem + 1vw, 1.5rem) media query nélkül, simán nő a képernyővel. A min() és a max() a kisebb vagy nagyobb értéket választja, pl. width: min(100% - 2rem, 70ch).' },
  { topic: 'subgrid', keywords: ['subgrid', 'grid-template-rows: subgrid'], en: 'subgrid lets a nested grid reuse its parent’s tracks: a card set to grid-row: span 3; grid-template-rows: subgrid; lines up its title, text and button with the neighbouring cards even when their content lengths differ. Supported in all modern browsers since 2023.', hu: 'A subgrid révén egy beágyazott grid a szülője sávjait használja: egy grid-row: span 3; grid-template-rows: subgrid; kártya címe, szövege és gombja egy vonalba kerül a szomszéd kártyákéval, akkor is, ha eltérő hosszú a tartalmuk. 2023 óta minden modern böngésző támogatja.' },
  { topic: 'view-transitions', keywords: ['view transition', 'view transitions', 'startviewtransition', 'oldalváltás animáció'], en: 'The View Transitions API animates between two states of a page: wrap a DOM update in document.startViewTransition(() => update()) and the browser cross-fades the old and new snapshot; elements with the same view-transition-name morph into each other. For multi-page sites, @view-transition { navigation: auto; } animates normal link navigations (Chromium and Safari).', hu: 'A View Transitions API az oldal két állapota között animál: a DOM-frissítést document.startViewTransition(() => update())-ba csomagolod, és a böngésző átúsztatja a régi és az új képet; az azonos view-transition-name-ű elemek egymásba alakulnak. Többoldalas webhelyen az @view-transition { navigation: auto; } a sima linkes navigációt animálja (Chromium és Safari).' },
  { topic: 'scroll-driven-animations', keywords: ['scroll-driven', 'scroll driven animation', 'scroll animation', 'görgetésre animáció', 'animation-timeline'], en: 'Scroll-driven animations tie a CSS animation to scrolling instead of time: animation-timeline: scroll() follows the page scroll (a reading-progress bar), and animation-timeline: view() runs while an element crosses the viewport (fade-in on reveal) — no JavaScript. Supported in Chromium and Safari; wrap it in @supports and keep a static fallback.', hu: 'A görgetésvezérelt animáció az időzítés helyett a görgetéshez köti a CSS-animációt: az animation-timeline: scroll() az oldal görgetését követi (olvasási csík), az animation-timeline: view() pedig akkor fut, amíg az elem átér a képernyőn (megjelenéskori beúszás) — JavaScript nélkül. Chromium és Safari támogatja; tedd @supports-ba, és legyen statikus tartalék.' },
  { topic: 'modern-css', keywords: ['modern css', 'new css features', 'új css', 'css újdonság', 'css ujdonsag'], en: 'Modern CSS worth knowing: container queries, :has(), native nesting, cascade layers, subgrid, clamp() for fluid sizes, color-mix() and oklch() colours, text-wrap: balance for headlines, accent-color for form controls, aspect-ratio, logical properties (margin-inline, padding-block), @starting-style for entry animations, the popover attribute, view transitions and scroll-driven animations.', hu: 'Érdemes ismerni a modern CSS-t: container query, :has(), natív beágyazás, cascade layerek, subgrid, clamp() a folyékony méretekhez, color-mix() és oklch() színek, text-wrap: balance a címekhez, accent-color az űrlapelemekhez, aspect-ratio, logikai tulajdonságok (margin-inline, padding-block), @starting-style a belépő animációkhoz, a popover attribútum, a view transitions és a görgetésvezérelt animációk.' },

  // ── typography ───────────────────────────────────────────────────────────────
  { topic: 'typography', keywords: ['typography', 'tipográfia', 'tipografia', 'line-height', 'sormagasság', 'sormagassag', 'line length', 'sorhossz'], en: 'Good web typography: body text at least 16px, line-height about 1.5 for paragraphs and 1.1–1.25 for headings, lines of 45–75 characters (max-width: 65ch), a clear size scale (for example a 1.25 ratio: 16, 20, 25, 31, 39px), at most two font families, and weights used for hierarchy (400 body, 600–700 headings). Left-aligned text reads best.', hu: 'Jó webes tipográfia: a folyószöveg legalább 16px, a sormagasság bekezdésnél kb. 1.5, címnél 1.1–1.25, a sorhossz 45–75 karakter (max-width: 65ch), világos méretskála (pl. 1.25-ös arány: 16, 20, 25, 31, 39px), legfeljebb két betűcsalád, és a vastagság jelzi a hierarchiát (400 szöveg, 600–700 cím). A balra zárt szöveg olvasható a legjobban.' },
  { topic: 'font-pairing', keywords: ['font pairing', 'font combination', 'betűtípus párosítás', 'betűpár', 'which font', 'milyen betűtípus'], en: 'Pair fonts by contrast, not similarity: a serif or a characterful display face for headings with a clean sans-serif for body text — or one versatile family (Inter, Roboto, Source Sans) in several weights. Check readability at small sizes, support for the characters you need (Hungarian ő and ű!), and keep it to two families.', hu: 'A betűtípusokat kontraszt, ne hasonlóság alapján párosítsd: talpas vagy karakteres display betű a címekhez, tiszta talpatlan a szöveghez — vagy egyetlen sokoldalú család (Inter, Roboto, Source Sans) több vastagságban. Nézd meg az olvashatóságot kis méretben és a szükséges karaktereket (magyar ő és ű!), és maradj két családnál.' },
  { topic: 'web-fonts', keywords: ['web font', 'webfont', '@font-face', 'font-display', 'google fonts', 'betűtípus betöltés', 'font loading'], en: 'Load web fonts efficiently: self-host WOFF2 files with @font-face (no third-party request), use font-display: swap so text shows immediately, preload the one or two most important files, subset to the characters you need, and prefer a variable font when you need many weights. System font stacks (system-ui) cost nothing to load.', hu: 'A webfontokat hatékonyan töltsd: WOFF2 fájlokat szolgálj ki magad @font-face-szel (nincs külső kérés), használj font-display: swap-ot, hogy a szöveg azonnal látsszon, preloadold a legfontosabb egy-két fájlt, szűkítsd a szükséges karakterekre, és sok vastagsághoz válassz variable fontot. A rendszerbetűk (system-ui) betöltése semmibe sem kerül.' },

  // ── colour ───────────────────────────────────────────────────────────────────
  { topic: 'color-theory', keywords: ['color theory', 'colour theory', 'színelmélet', 'szinelmelet', 'color wheel', 'színkör', 'complementary color', 'kiegészítő szín'], en: 'Colour theory basics: hue is the colour itself, saturation its intensity, lightness how light or dark it is. Harmonies come from the colour wheel — monochromatic (one hue, many shades), analogous (neighbours), complementary (opposites, strong contrast) and triadic. Warm colours advance and excite, cool colours recede and calm.', hu: 'Színelméleti alapok: a színárnyalat (hue) maga a szín, a telítettség az intenzitása, a világosság pedig hogy mennyire világos vagy sötét. A harmóniák a színkörből jönnek — monokróm (egy szín sok árnyalata), analóg (szomszédok), komplementer (ellentétek, erős kontraszt) és triádikus. A meleg színek előrelépnek és élénkítenek, a hideg színek hátralépnek és nyugtatnak.' },
  { topic: 'color-palette', keywords: ['color palette', 'colour palette', 'színpaletta', 'szinpaletta', '60-30-10 szabály', '60-30-10 rule', '60-30-10', 'brand color', 'which colors', 'milyen színeket'], en: 'Build a UI palette from roles, not random colours: one primary brand colour for actions, neutrals (greys, often slightly tinted) for text, backgrounds and borders, and semantic colours for success, warning, error and info. Give each a 50–950 shade scale. The 60-30-10 rule — 60% neutral, 30% secondary, 10% accent — keeps it calm and focused.', hu: 'A UI-palettát szerepekből építsd, ne véletlen színekből: egy elsődleges márkaszín a műveletekhez, semleges színek (szürkék, gyakran enyhén színezve) a szövegre, hátterekre és keretekre, valamint szemantikus színek a sikerhez, figyelmeztetéshez, hibához és infóhoz. Mindegyik kapjon 50–950-es árnyalatskálát. A 60-30-10 szabály — 60% semleges, 30% másodlagos, 10% kiemelő — nyugodt és fókuszált marad.' },
  { topic: 'color-formats', keywords: ['hex color', 'hex szín', 'hsl color', 'rgb color', 'oklch', 'color-mix', 'színkód', 'szinkod', 'css color format'], en: 'CSS colour formats: hex (#3b82f6), rgb(59, 130, 246), hsl(217 91% 60%) which is easy to tweak by hand, and oklch(0.62 0.19 260) whose lightness is perceptually even — ideal for generating shade scales. color-mix(in oklch, var(--primary), white 20%) mixes colours right in CSS.', hu: 'CSS színformátumok: hex (#3b82f6), rgb(59, 130, 246), a kézzel könnyen hangolható hsl(217 91% 60%), és az oklch(0.62 0.19 260), amelynek a világossága érzékelésben egyenletes — ideális árnyalatskálák generálásához. A color-mix(in oklch, var(--primary), white 20%) közvetlenül CSS-ben kever színeket.' },
  { topic: 'color-psychology', keywords: ['color psychology', 'colour psychology', 'színpszichológia', 'szinpszichologia', 'meaning of colors', 'színek jelentése'], en: 'Colours carry associations (they vary by culture): blue — trust, calm, tech and finance; green — growth, health, success; red — urgency, energy, errors; orange and yellow — friendliness, attention; purple — creativity, luxury; black and white — elegance and simplicity. Use them for meaning, but never rely on colour alone to convey information.', hu: 'A színeknek asszociációi vannak (kultúránként eltérnek): kék — bizalom, nyugalom, technológia és pénzügy; zöld — növekedés, egészség, siker; piros — sürgősség, energia, hiba; narancs és sárga — barátságosság, figyelemfelkeltés; lila — kreativitás, luxus; fekete-fehér — elegancia és egyszerűség. Használd őket jelentésre, de az információt soha ne csak színnel közöld.' },
  { topic: 'dark-mode', keywords: ['dark mode', 'dark theme', 'sötét mód', 'sotet mod', 'sötét téma', 'sotet tema', 'light mode', 'prefers-color-scheme', 'theme toggle'], en: 'Good dark mode is not just inverted colours: use dark greys (#0f1115 to #1e1e24) instead of pure black, off-white text instead of pure white, slightly desaturated accent colours, and show elevation with lighter surfaces rather than shadows. Drive it with CSS variables, follow prefers-color-scheme by default, set color-scheme: light dark, and let the user override it.', hu: 'A jó sötét mód nem csak invertált szín: tiszta fekete helyett sötétszürkét (#0f1115–#1e1e24), tiszta fehér helyett törtfehér szöveget, kissé tompított kiemelő színeket használj, a mélységet pedig világosabb felületekkel jelezd árnyék helyett. CSS-változókkal vezéreld, alapból kövesd a prefers-color-scheme-et, állítsd be a color-scheme: light dark-ot, és a felhasználó felülírhassa.' },

  // ── accessibility ────────────────────────────────────────────────────────────
  { topic: 'contrast', keywords: ['contrast ratio', 'color contrast', 'kontraszt', 'kontrasztarány', 'wcag', 'wcag contrast'], en: 'WCAG contrast minimums: normal text at least 4.5:1 against its background (AA), large text (24px, or about 18.5px bold) and UI parts such as input borders and icons at least 3:1; AAA asks for 7:1. Light-grey text on white is the most common failure — check every colour pair with a contrast checker.', hu: 'A WCAG kontrasztminimumai: a normál szöveg legalább 4.5:1 a hátteréhez képest (AA), a nagy szöveg (24px vagy kb. 18.5px félkövér) és a UI-elemek, például mezőkeretek és ikonok legalább 3:1; az AAA 7:1-et kér. A leggyakoribb hiba a fehéren világosszürke szöveg — minden színpárt ellenőrizz kontrasztmérővel.' },
  { topic: 'web-accessibility', keywords: ['web accessibility', 'accessibility', 'akadálymentesség', 'akadalymentesseg', 'a11y', 'accessible design', 'akadálymentes dizájn'], en: 'Accessible design: enough contrast, visible :focus-visible styles, real <button> and <a> elements, labels on every input, alt text on meaningful images, text that can zoom to 200%, touch targets at least 24×24px (44px is better), no information by colour alone, and prefers-reduced-motion respected for animations.', hu: 'Akadálymentes dizájn: elég kontraszt, látható :focus-visible stílus, valódi <button> és <a> elemek, címke minden mezőn, alt szöveg a fontos képeken, 200%-ig nagyítható szöveg, legalább 24×24px (inkább 44px) érintési célpont, semmi információ csak színnel, és az animációknál a prefers-reduced-motion tiszteletben tartása.' },
  { topic: 'focus-styles', keywords: ['focus style', 'focus-visible', 'focus ring', 'fókuszkeret', 'fokuszkeret', 'outline none'], en: 'Never remove focus outlines without a replacement: keyboard users need to see where they are. Style :focus-visible (shown for keyboard, not mouse clicks) with a clear 2–3px outline in a contrasting colour and an outline-offset, for example outline: 3px solid var(--primary); outline-offset: 2px.', hu: 'Soha ne vedd el a fókuszkeretet pótlás nélkül: a billentyűzettel navigálóknak látniuk kell, hol vannak. A :focus-visible-t (billentyűzetnél látszik, egérkattintásnál nem) jól látható, 2–3px-es, kontrasztos keret mutassa outline-offsettel, például outline: 3px solid var(--primary); outline-offset: 2px.' },
  { topic: 'reduced-motion', keywords: ['reduced motion', 'prefers-reduced-motion', 'csökkentett mozgás', 'motion sickness'], en: 'Some people get dizzy from motion. Wrap large or parallax animations in @media (prefers-reduced-motion: no-preference) { … }, or switch them off inside @media (prefers-reduced-motion: reduce), keeping only quick fades. Never autoplay big moving content without a way to pause it.', hu: 'Van, akit szédít a mozgás. A nagy vagy parallax animációkat tedd @media (prefers-reduced-motion: no-preference) { … } blokkba, vagy kapcsold ki őket @media (prefers-reduced-motion: reduce) alatt, csak rövid áttűnéseket hagyva. Nagy mozgó tartalmat soha ne indíts automatikusan megállítási lehetőség nélkül.' },

  // ── visual design principles ─────────────────────────────────────────────────
  { topic: 'visual-hierarchy', keywords: ['visual hierarchy', 'vizuális hierarchia', 'vizualis hierarchia', 'design hierarchy'], en: 'Visual hierarchy tells the eye what to read first. Create it with size, weight, colour and contrast, position (top-left first) and whitespace — one clear primary action per screen, secondary actions quieter. De-emphasise less important things (smaller, lighter grey) rather than shouting everything.', hu: 'A vizuális hierarchia megmutatja a szemnek, mit olvasson először. Méret, vastagság, szín és kontraszt, elhelyezés (balra fent az első) és üres tér teremti meg — képernyőnként egy egyértelmű fő művelet, a másodlagosak halkabbak. A kevésbé fontosat inkább halkítsd (kisebb, világosabb szürke), mint hogy mindent kiabálj.' },
  { topic: 'spacing', keywords: ['spacing scale', 'spacing system', 'térköz', 'terkoz', 'whitespace', 'white space', 'negative space', '8px grid', '8pt grid', 'üres tér'], en: 'Use a consistent spacing scale — multiples of 4 or 8px (4, 8, 12, 16, 24, 32, 48, 64) — instead of random values. Whitespace groups related things and separates unrelated ones (proximity), so put less space inside a group than between groups. When in doubt, add more space: crowded layouts look cheap, generous ones look calm and premium.', hu: 'Használj következetes térközskálát — 4 vagy 8px többszöröseit (4, 8, 12, 16, 24, 32, 48, 64) — véletlen értékek helyett. Az üres tér csoportosítja az összetartozót és elválasztja a különállót (közelség), ezért csoporton belül kevesebb hely legyen, mint csoportok között. Kétség esetén adj több helyet: a zsúfolt elrendezés olcsónak, a levegős nyugodtnak és prémiumnak hat.' },
  { topic: 'gestalt', keywords: ['gestalt', 'gestalt principles', 'gestalt elvek', 'law of proximity', 'design principles', 'tervezési elvek', 'dizájn alapelvek'], en: 'Gestalt principles explain how we group what we see: proximity (close things belong together), similarity (same look means same function), common region (a shared box or background groups items), continuity, closure and figure–ground. Combine them with alignment, repetition and contrast and most layouts start to look intentional.', hu: 'A Gestalt-elvek megmagyarázzák, hogyan csoportosítjuk a látottakat: közelség (ami közel van, összetartozik), hasonlóság (azonos kinézet = azonos funkció), közös terület (közös keret vagy háttér csoportosít), folytonosság, zártság és alak–háttér viszony. Igazítással, ismétléssel és kontraszttal együtt a legtöbb elrendezés tudatosnak hat.' },
  { topic: 'ui-ux', keywords: ['ui design', 'ux design', 'ui and ux', 'ui ux', 'user experience', 'felhasználói élmény', 'felhasznaloi elmeny', 'user interface design'], en: 'UI design is how the interface looks and feels — layout, colour, type, components and states. UX design is whether the whole experience works — research, user flows, information architecture, wireframes, prototypes and usability tests. Good UX makes the task easy; good UI makes it clear and pleasant.', hu: 'A UI-dizájn az, hogyan néz ki és milyen érzés a felület — elrendezés, szín, betű, komponensek és állapotok. A UX-dizájn az, hogy az egész élmény működik-e — kutatás, felhasználói utak, információs architektúra, drótvázak, prototípusok és használhatósági tesztek. A jó UX könnyűvé teszi a feladatot, a jó UI érthetővé és kellemessé.' },
  { topic: 'ux-laws', keywords: ['laws of ux', 'ux laws', "fitts's law", 'fitts law', "hick's law", 'hick law', "jakob's law", 'ux törvények'], en: 'Laws of UX in one line each: Fitts — big, close targets are faster to hit; Hick — more choices mean slower decisions; Jakob — users expect your site to work like the sites they already know; Miller — group information into small chunks; Doherty — respond in under 400 ms; aesthetic-usability — good-looking interfaces feel easier to use.', hu: 'A UX-törvények egy-egy sorban: Fitts — a nagy, közeli célpont gyorsabban eltalálható; Hick — több választás lassabb döntés; Jakob — a felhasználó azt várja, hogy az oldalad úgy működjön, mint a már ismertek; Miller — csoportosítsd kis egységekbe az információt; Doherty — 400 ms alatt reagálj; esztétika–használhatóság — a szép felület könnyebben használhatónak tűnik.' },
  { topic: 'design-system', keywords: ['design system', 'dizájnrendszer', 'design token', 'design tokens', 'style guide', 'stílusútmutató', 'component library'], en: 'A design system is the single source of truth for a product’s look: design tokens (colours, type scale, spacing, radii, shadows, motion as named variables), reusable components with all their states (hover, focus, disabled, error, loading), usage guidelines and accessibility rules — shared by designers (Figma) and developers (CSS variables, React components).', hu: 'A dizájnrendszer egy termék megjelenésének egyetlen forrása: design tokenek (színek, betűskála, térközök, sarokívek, árnyékok, mozgás elnevezett változóként), újrahasználható komponensek minden állapotukkal (hover, fókusz, letiltott, hiba, töltés), használati irányelvek és akadálymentességi szabályok — közösen a tervezőknek (Figma) és a fejlesztőknek (CSS-változók, React-komponensek).' },
  { topic: 'wireframe', keywords: ['wireframe', 'drótváz', 'drotvaz', 'mockup', 'ui prototype', 'figma prototípus', 'figma'], en: 'Design goes from rough to real: a wireframe is a low-fidelity grey sketch of the layout and content, a mockup adds the real colours, type and images, and a prototype makes it clickable to test the flow. Figma is the most common tool; design in real content and at real screen sizes.', hu: 'A tervezés durvából halad a valódi felé: a drótváz (wireframe) az elrendezés és a tartalom szürke, vázlatos terve, a mockup hozzáadja a valódi színeket, betűket és képeket, a prototípus pedig kattinthatóvá teszi, hogy tesztelhető legyen a folyamat. A leggyakoribb eszköz a Figma; valódi tartalommal és valódi képernyőméreten tervezz.' },
  { topic: 'grid-system', keywords: ['grid system', '12 column grid', '12-column grid', '12 oszlopos', 'rácsrendszer', 'column grid', 'gutter'], en: 'A grid system aligns a page to columns: classic web grids use 12 columns (they divide into halves, thirds and quarters) with fixed gutters and outer margins, collapsing to 4–8 columns on mobile. In CSS: grid-template-columns: repeat(12, 1fr); gap: 24px; then elements span columns with grid-column: span 6.', hu: 'A rácsrendszer oszlopokhoz igazítja az oldalt: a klasszikus webes rács 12 oszlopos (felezhető, harmadolható, negyedelhető), fix hasábközökkel és külső margóval, mobilon 4–8 oszlopra szűkül. CSS-ben: grid-template-columns: repeat(12, 1fr); gap: 24px; az elemek pedig grid-column: span 6-tal fognak át oszlopokat.' },

  // ── UI components & patterns ─────────────────────────────────────────────────
  { topic: 'button-design', keywords: ['button design', 'button style', 'gomb dizájn', 'gombstílus', 'gomb stílus', 'cta button', 'call to action'], en: 'Good buttons: a clear verb label ("Save changes"), enough padding (about 10px 18px, at least 40–44px tall), one filled primary button per view with outline or ghost buttons for secondary actions, a visible hover, active and :focus-visible state, a disabled look that is still readable, and a loading state for slow actions.', hu: 'Jó gombok: egyértelmű, igei felirat („Változások mentése”), elég padding (kb. 10px 18px, legalább 40–44px magas), nézetenként egy kitöltött elsődleges gomb, a másodlagos műveletekhez körvonalas vagy szellemgomb, látható hover-, aktív és :focus-visible állapot, olvasható letiltott kinézet, és töltésjelzés a lassú műveleteknél.' },
  { topic: 'card-design', keywords: ['card design', 'card component', 'kártya dizájn', 'kártya komponens', 'card ui'], en: 'A card groups one item: image or icon, title, a short text and one action. Give it padding (16–24px), a subtle border or soft shadow, a radius matching the rest of the UI (8–16px), consistent image ratios (aspect-ratio + object-fit: cover), and if the whole card is clickable, a single link stretched over it with a hover lift.', hu: 'A kártya egy elemet foglal össze: kép vagy ikon, cím, rövid szöveg és egy művelet. Kapjon paddinget (16–24px), finom keretet vagy lágy árnyékot, a UI többi részével egyező lekerekítést (8–16px), egységes képarányt (aspect-ratio + object-fit: cover), és ha az egész kártya kattintható, egyetlen, ráfeszített linket enyhe hover-emelkedéssel.' },
  { topic: 'form-design', keywords: ['form design', 'form ux', 'űrlap dizájn', 'urlap dizajn', 'input design', 'form styling', 'űrlap stílus'], en: 'Usable forms: one column, labels above the fields (never placeholder-only), fields sized to the expected input, related fields grouped, the right input types (email, tel, number) and autocomplete attributes, inline errors next to the field in plain language, a clear focus state, and a primary submit button that says what happens.', hu: 'Használható űrlap: egy oszlop, a címkék a mezők fölött (soha ne csak placeholder), a várt bevitelhez méretezett mezők, csoportosított összetartozó mezők, megfelelő input típusok (email, tel, number) és autocomplete attribútumok, közérthető hibaüzenet közvetlenül a mező mellett, jól látható fókusz, és egy elsődleges küldés gomb, amely kimondja, mi történik.' },
  { topic: 'navigation-design', keywords: ['navbar design', 'navigation bar', 'navigációs sáv', 'navigacios sav', 'hamburger menu', 'hamburger menü', 'site navigation'], en: 'Navigation: keep 5–7 top-level items with short labels, highlight the current page, put the logo on the left linking home, make the header sticky only if it is slim, collapse into a hamburger or bottom bar on mobile, and keep the menu reachable by keyboard (a real <button> with aria-expanded).', hu: 'Navigáció: 5–7 főmenüpont rövid felirattal, kiemelt aktuális oldal, balra a főoldalra mutató logó, ragadós fejléc csak ha keskeny, mobilon hamburger- vagy alsó sáv, és billentyűzettel is elérhető menü (valódi <button> aria-expanded attribútummal).' },
  { topic: 'hero-section', keywords: ['hero section', 'hero szekció', 'hero szekcio', 'above the fold', 'landing page design', 'nyitóoldal dizájn'], en: 'A strong hero section: one clear headline that says what it is and for whom, a one-sentence subheading, one primary call to action (plus an optional secondary), and a supporting visual — product shot, illustration or subtle gradient. Keep the text left- or centre-aligned, high contrast, and visible without scrolling on a laptop.', hu: 'Erős hero szekció: egy egyértelmű főcím arról, mi ez és kinek szól, egy mondatos alcím, egy elsődleges cselekvésre hívó gomb (opcionálisan egy másodlagos), és egy támogató vizuális elem — termékkép, illusztráció vagy finom színátmenet. A szöveg legyen balra vagy középre zárt, kontrasztos, és laptopon görgetés nélkül látszódjon.' },
  { topic: 'modal-design', keywords: ['modal design', 'modal dialog', 'dialog element', 'felugró ablak', 'modális ablak', 'popup design'], en: 'Use modals sparingly, for short focused tasks. The native <dialog> element with showModal() gives you the backdrop, focus trapping and Esc-to-close for free; style ::backdrop, give the dialog a clear title, a close button and at most two actions, and return focus to the trigger when it closes.', hu: 'Modális ablakot ritkán, rövid, fókuszált feladatra használj. A natív <dialog> elem showModal()-lal ingyen adja a hátteret, a fókusz bent tartását és az Esc-re zárást; stílusozd a ::backdrop-ot, adj egyértelmű címet, bezáró gombot és legfeljebb két műveletet, bezáráskor pedig vidd vissza a fókuszt az indító elemre.' },
  { topic: 'loading-states', keywords: ['skeleton screen', 'skeleton loader', 'loading state', 'töltésjelző', 'toltesjelzo', 'spinner', 'empty state', 'üres állapot'], en: 'Design every state, not just the happy one: skeleton screens (grey placeholder shapes with a soft shimmer) feel faster than spinners for content, spinners suit short actions, progress bars long ones; empty states should explain what goes here and offer the first action; error states say what went wrong and how to fix it.', hu: 'Minden állapotot tervezz meg, ne csak a sikereset: tartalomnál a skeleton (szürke helykitöltő formák finom csillogással) gyorsabbnak hat a pörgőnél, rövid műveletre a spinner, hosszúra a folyamatjelző való; az üres állapot mondja el, mi kerül ide, és kínálja fel az első lépést; a hibaállapot mondja meg, mi romlott el és hogyan javítható.' },

  // ── styles & effects ─────────────────────────────────────────────────────────
  { topic: 'shadows', keywords: ['box-shadow', 'box shadow', 'drop shadow', 'css shadow', 'css árnyék', 'árnyék css', 'elevation', 'shadow css'], en: 'Realistic shadows are soft and layered: combine a tight, darker shadow with a wide, faint one — box-shadow: 0 1px 2px rgb(0 0 0 / 0.06), 0 8px 24px rgb(0 0 0 / 0.08). Use a small elevation scale (e.g. 3–5 levels) so higher things cast bigger shadows, tint shadows with the background hue, and lighten surfaces instead in dark mode.', hu: 'A valósághű árnyék lágy és rétegzett: kombinálj egy szűk, sötétebb és egy széles, halvány árnyékot — box-shadow: 0 1px 2px rgb(0 0 0 / 0.06), 0 8px 24px rgb(0 0 0 / 0.08). Használj kis mélységskálát (pl. 3–5 szint), hogy a magasabb elem nagyobb árnyékot vessen, színezd az árnyékot a háttér árnyalatával, sötét módban pedig inkább világosítsd a felületet.' },
  { topic: 'gradients', keywords: ['css gradient', 'linear-gradient', 'radial-gradient', 'conic-gradient', 'színátmenet', 'szinatmenet', 'gradient background', 'gradient text'], en: 'CSS gradients are images: linear-gradient(135deg, #6366f1, #ec4899) for backgrounds, radial-gradient for glows and spotlights, conic-gradient for pie charts and rings. Interpolate in oklch for smoother, less muddy blends (linear-gradient(in oklch, …)), and make gradient text with background-clip: text and a transparent colour.', hu: 'A CSS színátmenetek képek: linear-gradient(135deg, #6366f1, #ec4899) háttérnek, radial-gradient ragyogáshoz és spotlámpához, conic-gradient kördiagramhoz és gyűrűhöz. Az oklch-ban interpolált átmenet simább, kevésbé szürkül (linear-gradient(in oklch, …)), a színátmenetes szöveghez pedig background-clip: text és átlátszó szín kell.' },
  { topic: 'glassmorphism', keywords: ['glassmorphism', 'glass effect', 'glass card', 'üveghatás', 'uveghatas', 'frosted glass', 'backdrop-filter'], en: 'Glassmorphism = a translucent, blurred panel over a colourful background: background: rgb(255, 255, 255, 0.12); backdrop-filter: blur(16px) saturate(140%); a 1px light border and a soft shadow. It only works over a busy or gradient background; keep text contrast high and provide a solid fallback where backdrop-filter is unsupported.', hu: 'Glassmorphism = áttetsző, elmosott panel színes háttér fölött: background: rgb(255, 255, 255, 0.12); backdrop-filter: blur(16px) saturate(140%); 1px-es világos keret és lágy árnyék. Csak mozgalmas vagy színátmenetes háttéren működik; tartsd magasan a szöveg kontrasztját, és ahol nincs backdrop-filter, legyen tömör tartalék.' },
  { topic: 'neumorphism', keywords: ['neumorphism', 'neomorphism', 'neomorfizmus', 'soft ui'], en: 'Neumorphism ("soft UI") makes elements look extruded from the same-coloured background with two shadows, one light and one dark: box-shadow: 8px 8px 16px #c5c9d0, -8px -8px 16px #ffffff. It looks soft but has weak contrast, so use it for decoration and keep clear borders or colour for important controls.', hu: 'A neumorphism („soft UI”) azt mutatja, mintha az elem az azonos színű háttérből domborodna ki, két árnyékkal — egy világossal és egy sötéttel: box-shadow: 8px 8px 16px #c5c9d0, -8px -8px 16px #ffffff. Lágy hatású, de gyenge a kontrasztja, ezért díszítésre használd, a fontos vezérlők kapjanak egyértelmű keretet vagy színt.' },
  { topic: 'border-radius', keywords: ['border-radius', 'rounded corners', 'lekerekített sarok', 'lekerekites', 'pill shape'], en: 'Corner radius sets the personality: 0–4px feels sharp and serious, 8–16px friendly and modern, 9999px makes pills and circles. Keep one radius scale across the UI, and for nested shapes use outer radius = inner radius + padding so the curves stay parallel.', hu: 'A sarokív adja a felület karakterét: 0–4px éles és komoly, 8–16px barátságos és modern, a 9999px pirulát és kört ad. Tarts egységes sarokív-skálát az egész felületen, egymásba ágyazott formáknál pedig külső ív = belső ív + padding, hogy a görbék párhuzamosak maradjanak.' },
  { topic: 'css-animation', keywords: ['css animation', 'css animáció', 'css animacio', '@keyframes', 'keyframes', 'css transition', 'átmenet css'], en: 'CSS has two kinds of motion: transition animates a property change (transition: transform 200ms ease) — perfect for hovers; @keyframes with animation runs multi-step or looping motion. Animate only transform and opacity for smooth 60fps, keep UI motion short (150–300ms), use ease-out for things entering and ease-in for things leaving.', hu: 'A CSS-ben kétféle mozgás van: a transition egy tulajdonságváltozást animál (transition: transform 200ms ease) — hoverre tökéletes; a @keyframes az animation-nel többlépéses vagy ismétlődő mozgást futtat. Csak a transformot és az opacityt animáld a sima 60fps-ért, a UI-mozgás legyen rövid (150–300ms), belépésnél ease-out, kilépésnél ease-in.' },
  { topic: 'micro-interactions', keywords: ['micro-interaction', 'micro interaction', 'mikrointerakció', 'mikrointerakcio', 'easing', 'cubic-bezier', 'hover effect', 'hover effekt'], en: 'Micro-interactions are tiny feedback moments: a button that presses down, a heart that pops, a toggle that slides, a field that shakes on error. Make them fast (100–250ms), physical (custom easing like cubic-bezier(0.2, 0.8, 0.2, 1)), meaningful rather than decorative, and quiet under prefers-reduced-motion.', hu: 'A mikrointerakciók apró visszajelzések: lenyomódó gomb, kipattanó szív, elcsúszó kapcsoló, hibánál megrázkódó mező. Legyenek gyorsak (100–250ms), fizikaiak (egyedi easing, pl. cubic-bezier(0.2, 0.8, 0.2, 1)), jelentést hordozók és ne csak díszek, és prefers-reduced-motion mellett legyenek visszafogottak.' },
  { topic: 'css-transform', keywords: ['css transform', 'transform css', 'rotate css', 'scale css', 'css transzformáció'], en: 'transform moves, rotates, scales and skews an element without affecting layout: translate(0, -4px) for a hover lift, scale(1.05) for zoom, rotate(45deg) for an arrow. Individual properties (translate, rotate, scale) can now be set and animated separately, and transform-origin sets the pivot point.', hu: 'A transform elmozdít, forgat, nagyít és ferdít egy elemet az elrendezés befolyásolása nélkül: translate(0, -4px) hover-emeléshez, scale(1.05) nagyításhoz, rotate(45deg) nyílhoz. Az egyedi tulajdonságok (translate, rotate, scale) ma már külön is állíthatók és animálhatók, a transform-origin pedig a forgáspontot adja meg.' },
  { topic: 'images-css', keywords: ['object-fit', 'aspect-ratio', 'képarány', 'kepkarany', 'responsive image', 'reszponzív kép', 'image optimization', 'képoptimalizálás', 'lazy loading'], en: 'Images that look right and load fast: max-width: 100%; height: auto; to stay inside the layout, aspect-ratio plus object-fit: cover for uniform thumbnails without distortion, modern formats (AVIF, WebP), srcset/sizes so phones get small files, loading="lazy" below the fold, and width/height attributes to prevent layout shift.', hu: 'Jól kinéző és gyorsan töltő képek: max-width: 100%; height: auto; hogy az elrendezésen belül maradjanak, aspect-ratio és object-fit: cover az egységes, torzítatlan bélyegképekhez, modern formátumok (AVIF, WebP), srcset/sizes, hogy a telefon kis fájlt kapjon, loading="lazy" a hajtás alatt, és width/height attribútumok az elrendezés ugrálása ellen.' },
  { topic: 'icons', keywords: ['icon design', 'svg icon', 'ikonok', 'icon set', 'ikonkészlet', 'lucide', 'heroicons'], en: 'Use SVG icons from one consistent set (Lucide, Heroicons, Material Symbols, Phosphor) at a few fixed sizes (16, 20, 24px), coloured with currentColor so they follow the text. Pair icons with labels for anything important, give icon-only buttons an aria-label, and keep stroke widths consistent.', hu: 'Egységes készletből származó SVG ikonokat használj (Lucide, Heroicons, Material Symbols, Phosphor) néhány fix méretben (16, 20, 24px), currentColor színnel, hogy kövessék a szöveget. A fontos dolgoknál az ikon mellé írj feliratot, a csak ikonos gomb kapjon aria-labelt, a vonalvastagság legyen egységes.' },

  // ── tooling & methodology ────────────────────────────────────────────────────
  { topic: 'css-reset', keywords: ['css reset', 'modern css reset', 'normalize.css', 'normalize css', 'alapstílus'], en: 'A modern CSS reset is a few lines: *, *::before, *::after { box-sizing: border-box; } remove default margins, body { line-height: 1.5; -webkit-font-smoothing: antialiased; } img, picture, svg, video { display: block; max-width: 100%; } input, button, textarea, select { font: inherit; } and p, h1–h6 { overflow-wrap: break-word; }.', hu: 'A modern CSS reset néhány sor: *, *::before, *::after { box-sizing: border-box; }, az alap margók törlése, body { line-height: 1.5; -webkit-font-smoothing: antialiased; }, img, picture, svg, video { display: block; max-width: 100%; }, input, button, textarea, select { font: inherit; }, valamint p és h1–h6 { overflow-wrap: break-word; }.' },
  { topic: 'sass', keywords: ['sass', 'scss', 'css preprocessor', 'css előfeldolgozó', 'less css'], en: 'Sass (SCSS syntax) is a CSS preprocessor: variables ($primary), nesting, mixins, functions, loops and partials compiled into plain CSS. Much of it is now native CSS — custom properties, nesting, color-mix(), clamp() — so many new projects use plain CSS or PostCSS, while Sass stays popular in large codebases and Bootstrap.', hu: 'A Sass (SCSS szintaxis) CSS-előfeldolgozó: változók ($primary), beágyazás, mixinek, függvények, ciklusok és részfájlok, amelyekből sima CSS fordul. Ennek nagy része ma már natív CSS — egyéni tulajdonságok, beágyazás, color-mix(), clamp() —, ezért sok új projekt sima CSS-t vagy PostCSS-t használ, a Sass pedig a nagy kódbázisokban és a Bootstrapben népszerű.' },
  { topic: 'bem', keywords: ['bem naming', 'bem method', 'bem methodology', 'bem módszer', 'block element modifier', 'css naming convention', 'css elnevezési'], en: 'BEM (Block, Element, Modifier) is a CSS naming convention: .card is a block, .card__title an element inside it, .card--featured a variant. Flat, single-class selectors keep specificity low and make it obvious where a style belongs; CSS Modules and utility frameworks solve the same problem differently.', hu: 'A BEM (Block, Element, Modifier) CSS-elnevezési konvenció: a .card blokk, a .card__title a benne lévő elem, a .card--featured egy változat. A lapos, egyosztályos szelektorok alacsonyan tartják a specificitást, és egyértelművé teszik, hova tartozik egy stílus; a CSS Modules és a utility keretrendszerek ugyanezt másképp oldják meg.' },
  { topic: 'css-frameworks', keywords: ['css framework', 'css keretrendszer', 'utility-first', 'utility first', 'which css framework', 'melyik css keretrendszer'], en: 'CSS frameworks: Tailwind CSS (utility classes in the markup, fast to build, consistent tokens), Bootstrap (ready components and a 12-column grid), and component libraries like MUI, Chakra or shadcn/ui for React. For a small site, plain modern CSS with variables is often enough; pick one approach per project.', hu: 'CSS-keretrendszerek: Tailwind CSS (utility osztályok a markupban, gyors építés, egységes tokenek), Bootstrap (kész komponensek és 12 oszlopos rács), valamint komponenskönyvtárak, mint az MUI, a Chakra vagy a shadcn/ui Reacthez. Kis oldalhoz gyakran elég a sima modern CSS változókkal; projektenként egy megközelítést válassz.' },
  { topic: 'ui-trends', keywords: ['ui trends', 'design trends', 'dizájn trendek', 'dizajn trendek', 'bento grid', 'bento layout'], en: 'Recent UI trends: bento grids (cards of different sizes in one tidy grid), big bold typography, soft gradients and mesh backgrounds, glass panels, dark-first interfaces, subtle grain and noise textures, playful 3D and micro-interactions, and minimal interfaces with lots of whitespace. Use a trend only when it serves the content.', hu: 'Friss UI-trendek: bento rács (különböző méretű kártyák egy rendezett rácsban), nagy, merész tipográfia, lágy színátmenetek és mesh hátterek, üvegpanelek, sötét alapú felületek, finom szemcsés textúrák, játékos 3D és mikrointerakciók, valamint sok üres teret hagyó minimalista felületek. Trendet csak akkor használj, ha a tartalmat szolgálja.' },
];

